# ---------------------------------------------------------------- synthetic driving
# (length m, signed curvature 1/m) pieces: a made-up circuit with six corners
PIECES = [(500, 0), (94, 1 / 60), (300, 0), (180, -1 / 85), (420, 0), (110, 1 / 35), (350, 0),
          (120, -1 / 75), (140, 0), (110, 1 / 70), (260, 0), (90, -1 / 55), (380, 0)]
TOTAL = sum(p[0] for p in PIECES)

def curv_at(s):
    s = s % TOTAL
    acc = 0.0
    for L, k in PIECES:
        if s < acc + L:
            return k
        acc += L
    return 0.0

def target_speed(s, scale, brake_off):
    """km/h the driver wants at distance s: corner-limited, braking early enough for what is ahead."""
    best = 255.0
    for ahead in range(0, 700, 5):
        k = abs(curv_at(s + ahead + brake_off))
        if k > 0:
            vc = math.sqrt(12.0 * scale / k)                    # m/s the corner allows
            best = min(best, 3.6 * math.sqrt(vc * vc + 2 * 15.0 * ahead))
    return best

def drive(seed, scale=1.0, brake_off=0.0, accel=1.0, hz=10, rate_k=1.0, fuel0=62.0, laps=1, lap_number_start=1, extra_noise=0.0,
          pit_after=None):
    rng = np.random.default_rng(seed)
    dt = 1.0 / hz
    s = 0.0; v = 20.0; t = 0.0; heading = 0.3; x = 100.0; z = -50.0
    fuel = fuel0; rows = []; lapno = lap_number_start; gear = 2
    lap_len_done = 0.0
    gear_ratios = [3.2, 2.1, 1.55, 1.2, 0.98, 0.8, 0.68]
    pit = False
    while True:
        k = curv_at(s)
        vt = target_speed(s, scale, brake_off)
        err = vt - v
        thr = float(np.clip(0.25 + err / 14.0 * accel, 0, 1)) if err > -2 else 0.0
        brk = float(np.clip(-err / 24.0, 0, 1)) if err < -4.0 else 0.0
        if pit:
            thr = min(thr, 0.2); brk = 0.0
        thr = float(np.clip(thr + rng.normal(0, 0.01 + extra_noise), 0, 1)) if thr > 0 else 0.0
        u = v / 3.6
        a = thr * 7.5 * accel - brk * 17.0 - 0.0004 * u * u - 0.25 * (1 - thr)
        v = max(30.0, v + a * dt * 3.6)
        ang_y = v / 3.6 * k + rng.normal(0, 0.002)
        steering = float(np.clip(k * 55 + rng.normal(0, 0.01), -1, 1))
        heading += k * v / 3.6 * dt
        x += math.sin(heading) * v / 3.6 * dt
        z += math.cos(heading) * v / 3.6 * dt
        gear = int(np.clip(1 + v // 38, 1, 7))
        rpm = float(2500 + (v / 3.6) * gear_ratios[gear - 1] * 9.0 * 5.0)
        rpm = float(np.clip(rpm, 1500, 8200))
        burn = (0.0012 + 0.0016 * thr) * dt * 10 * rate_k
        fuel = max(0.0, fuel - burn)
        slip = lambda b: round(1.0 + abs(k) * 6 * (1 if b else 0.8) + brk * 0.06 + rng.normal(0, 0.01), 4)
        tt = lambda b: round(70 + 12 * math.tanh(t / 40) + abs(ang_y) * 6 + b + rng.normal(0, 0.2), 3)
        row = {
            "t": round(t, 4), "world_x": round(x, 3), "world_y": 5.0, "world_z": round(z, 3), "heading": round(heading % (2 * math.pi) - math.pi, 5),
            "track_position": round(s, 3), "speed_kmh": round(v, 3), "vel_x": round(math.sin(heading) * v / 3.6, 4), "vel_y": round(rng.normal(0, 0.02), 4),
            "vel_z": round(math.cos(heading) * v / 3.6, 4), "ang_x": round(rng.normal(0, 0.01), 4), "ang_y": round(ang_y, 5), "ang_z": round(rng.normal(0, 0.01), 4),
            "throttle": round(thr, 4), "brake": round(brk, 4), "steering": round(steering, 4), "clutch": 0.0, "steering_source": "rotation",
            "clutch_engaged": 1, "gear": gear, "suggested_gear": gear if rng.random() > 0.15 else max(1, gear - 1), "rpm": round(rpm, 2), "max_rpm": 8500,
            "rpm_warning": 7500, "rpm_limiter": 8200, "rpm_after_clutch": round(rpm * 0.99, 2), "boost": round(0.4 + thr * 0.6, 4),
            "tyre_temp_fl": tt(2), "tyre_temp_fr": tt(0), "tyre_temp_rl": tt(-3), "tyre_temp_rr": tt(-4),
            "tyre_slip_fl": slip(1), "tyre_slip_fr": slip(1), "tyre_slip_rl": slip(0), "tyre_slip_rr": slip(0),
            "susp_fl": round(0.12 + rng.normal(0, 0.002), 5), "susp_fr": round(0.12 + rng.normal(0, 0.002), 5),
            "susp_rl": round(0.13 + rng.normal(0, 0.002), 5), "susp_rr": round(0.13 + rng.normal(0, 0.002), 5), "ride_height_mm": round(88 + rng.normal(0, 0.5), 3),
            "fuel_remaining": round(fuel, 4), "fuel_capacity": 100.0, "is_ev": False, "oil_temp": 95.0, "water_temp": 80.0, "oil_pressure": 4.5,
            "lap_number": lapno, "current_position": 3 if lapno == lap_number_start and t < 20 else -1, "total_positions": 12, "in_pit": False,
            "time_of_day": 43200000, "est_top_speed": 281, "car_id": 3300, "flags_8e": 0, "flags_8f": 0, "flags_93": 0,
            "wheel_rotation": round(steering * 3.0, 4), "steering_angular_velocity": round(rng.normal(0, 0.05), 4),
            "sway": round(rng.normal(0, 0.2), 4), "heave": round(rng.normal(0, 0.2), 4), "surge": round(rng.normal(0, 0.2), 4),
            "torque_vectors": [0.0, 0.0, 0.0, 0.0], "energy_recovery": 0.0, "throttle_filtered": round(thr, 4), "brake_filtered": round(brk, 4),
            "surface_type": "TTTT" if abs(k) < 1 / 50 else "TTCT", "current_lap_ms": int(t * 1000), "wheel_steering_angle_l": round(steering * 0.4, 4),
            "wheel_steering_angle_r": round(steering * 0.4, 4), "wheel_base": 2.55, "car_category": "N400",
        }
        rows.append(row)
        s += v / 3.6 * dt; t += dt
        if s >= TOTAL * (1 + 0.01 * (seed % 3 - 1)):
            if lapno - lap_number_start + 1 >= laps:
                break
            s = 0.0; lapno += 1
        if pit_after and lapno == pit_after and not pit and s > TOTAL * 0.7:
            pit = True
    return rows, round(t, 3), gear_ratios

def lap_file(rows, lap_time, ratios, rec="20260901_120000", car="Mazda MX-5 (ND)", track="red_bull_ring", era=None):
    d = {"recorded_at": rec, "track": track, "car": car, "track_display": "Red Bull Ring", "car_display": car,
         "lap_time_s": lap_time, "lap_distance_m": round(rows[-1]["track_position"], 1), "total_samples": len(rows),
         "incomplete": False, "physics_era": era or "1.71", "gear_ratios": ratios, "samples": rows}
    return d

def dumps(o):
    return json.dumps(o, separators=(",", ":"))

A, ta, gr = drive(1, scale=1.0, brake_off=0.0)
B, tb, _ = drive(2, scale=0.97, brake_off=-6.0, accel=0.93)
Cc, tc, _ = drive(4, scale=1.02, brake_off=4.0, accel=1.05)
files = {"lapA.json": lap_file(A, ta, gr), "lapB.json": lap_file(B, tb, gr, rec="20260902_130000"),
         "lapC.json": lap_file(Cc, tc, gr, rec="20260903_140000")}
# ghost: six channels only
ghost_samples = [{k: s[k] for k in ("track_position", "speed_kmh", "throttle", "brake", "steering", "gear")} for s in B[::2]]
files["ghost.json"] = {"car": "Mazda MX-5 (ND)", "track": "Red Bull Ring", "lap_time_s": tb, "samples": ghost_samples}
# race: 4 laps with a refuel after lap 2 (pit-lane slow stretch)
R, tr, _ = drive(7, laps=4, fuel0=52.0, lap_number_start=1, extra_noise=0.01)
# mark lap 0 grid roll: first 15 samples lap 0
for i in range(15): R[i]["lap_number"] = 0
# insert a pit stop: after lap 2 ends, slow samples with fuel ramping up
idx = next(i for i, r in enumerate(R) if r["lap_number"] == 3)
stop = []
base = R[idx - 1]
f = base["fuel_remaining"]
for j in range(40):
    r = dict(base); r["t"] = round(base["t"] + 0.1 * (j + 1), 4); r["speed_kmh"] = 55.0 if j < 8 or j > 31 else 0.0
    if 12 <= j <= 30: f += 1.2
    r["fuel_remaining"] = round(f, 4); r["lap_number"] = 2; r["throttle"] = 0.0; r["brake"] = 0.0
    r["track_position"] = base["track_position"]
    stop.append(r)
shift = 0.1 * 40
R2 = R[:idx] + stop
for r in R[idx:]:
    r2 = dict(r); r2["t"] = round(r["t"] + shift, 4); r2["fuel_remaining"] = round(r["fuel_remaining"] + (f - base["fuel_remaining"]), 4)
    R2.append(r2)
race = {"recorded_at": "20260905_180000", "track": "red_bull_ring", "car": "Mazda MX-5 (ND)", "track_display": "Red Bull Ring",
        "car_display": "Mazda MX-5 (ND)", "race_duration_s": round(R2[-1]["t"] - R2[0]["t"], 3), "physics_era": "1.71", "samples": R2}
files["race.json"] = race
for name, obj in files.items():
    open(f"{out}/{name}", "w").write(dumps(obj))

# ---------------------------------------------------------------- goldens
def arr(x): return [None if (isinstance(v, float) and math.isnan(v)) else float(v) for v in np.asarray(x, dtype=float)]

def corner_d(c):
    return {"number": c.number, "start": c.start, "end": c.end, "apex": c.apex, "brake_pos": c.brake_pos,
            "throttle_pos": c.throttle_pos, "min_speed": c.min_speed, "brake_peak": c.brake_peak, "trail": c.trail}
def delta_d(d):
    return {"number": d.number, "ref_number": d.ref_number, "brake_m": d.brake_m, "min_speed_kmh": d.min_speed_kmh,
            "throttle_m": d.throttle_m, "time_s": d.time_s}

