# theoretical
r = theoretical.theoretical_best([("Lap A", dfA), ("Lap B", dfB), ("Lap C", dfC)])
G["theory"] = {"labels": r["labels"], "totals": arr(r["totals"]), "best_idx": r["best_idx"], "actual": r["actual"], "theoretical": r["theoretical"],
               "gap": r["gap"], "centers": arr(r["centers"]), "donor": [int(x) for x in r["donor"]], "loss": arr(r["loss"]),
               "cum_gap": arr(r["cum_gap"]), "zones": r["zones"], "skipped": r["skipped"]}
G["theory_none"] = theoretical.theoretical_best([("Lap A", dfA)]) is None
# ratings / style (the PC computes these inside draw_ratings / draw_style: re-run here verbatim)
def lap_scores(d):
    steer_smooth = max(0.0, 1.0 - min(1.0, la._num(d["steering"].diff().fillna(0).std()) * 5)) * 100
    braking = d[d["brake"] > 0.1]
    brk_eff = (min(100.0, braking["speed_kmh"].mean() / max(1.0, d["speed_kmh"].mean()) * 100) if len(braking) > 10 else 50.0)
    not_brk = d[d["brake"] < 0.05]
    thr_app = float((not_brk["throttle"] > 0.85).mean() * 100) if len(not_brk) > 0 else 0.0
    cornering = d[d["lat_g"].abs() > 0.5]
    crn_spd = (min(100.0, cornering["speed_kmh"].mean() / max(1.0, d["speed_kmh"].max()) * 120) if len(cornering) > 10 else 50.0)
    has_sg = d["suggested_gear"].abs().max() > 0
    gear_m = float((d["gear"] == d["suggested_gear"]).mean() * 100) if has_sg else 60.0
    sec_avgs = [s["speed_kmh"].mean() for s in la.lap_sectors(d, 10)[0] if len(s)]
    consist = (max(0.0, min(100.0, 100.0 - np.std(sec_avgs) / max(1.0, np.mean(sec_avgs)) * 100)) if len(sec_avgs) >= 3 else 50.0)
    slip_var = float(d[["tyre_slip_rl", "tyre_slip_rr"]].std().mean())
    traction = max(0.0, 100.0 - slip_var * 20)
    return [steer_smooth, brk_eff, thr_app, crn_spd, gear_m, consist, traction]
G["scores_A"] = lap_scores(dfA); G["scores_B"] = lap_scores(dfB)

def style_metrics(d):
    step = d["t"].diff(); step = step[step > 1e-4]
    k = 0.1 / float(step.median()) if len(step) else 1.0
    dt = d["steering"].diff().abs().fillna(0) * k
    tt = d["throttle"].diff().abs().fillna(0) * k
    bt = d["brake"].diff().abs().fillna(0) * k
    aggression = float(min(100.0, (dt.mean() * 220 + tt.mean() * 140 + bt.mean() * 140)))
    corner = d[d["lat_g"].abs() > 0.5]
    if len(corner) > 10:
        front = corner[["tyre_slip_fl", "tyre_slip_fr"]].mean(axis=1)
        rear = corner[["tyre_slip_rl", "tyre_slip_rr"]].mean(axis=1)
        balance = float((rear - front).mean())
    else:
        balance = 0.0
    return aggression, balance, len(corner)
G["style_A"] = style_metrics(dfA); G["style_B"] = style_metrics(dfB)
G["brake_zones_A"] = arr(la_zones := [float(x) for x in __import__("gt7telem.lap_analyst", fromlist=["x"])._brake_zone_durations(dfA)])

def sector_stats(d, N=10):
    segs, times = la.lap_sectors(d, N)
    def agg(col, fn, scale=1.0):
        return [float(fn(s[col])) * scale if len(s) else float("nan") for s in segs]
    return {"times": arr(times), "avg": arr(agg("speed_kmh", np.mean)), "top": arr(agg("speed_kmh", np.max)),
            "brk": arr(agg("brake", np.mean, 100)), "thr": arr(agg("throttle", np.mean, 100)),
            "latg": arr([float(s["lat_g"].abs().max()) if len(s) else float("nan") for s in segs])}
G["sector_stats_A"] = sector_stats(dfA)
# telediff pieces (draw_telediff)
ta_ = (dfA["track_position"] / max(dfA["track_position"].max(), 1)).values
tb_ = (dfB["track_position"] / max(dfB["track_position"].max(), 1)).values
ta_s = np.sort(ta_); tb_s = np.sort(tb_)
vb_speed = np.interp(ta_s, tb_s, dfB.sort_values("track_position")["speed_kmh"].values)
va_speed = np.interp(ta_s, ta_s, dfA.sort_values("track_position")["speed_kmh"].values)
vb_t = np.interp(ta_s, tb_s, dfB.sort_values("track_position")["t"].values)
va_t = np.interp(ta_s, ta_s, dfA.sort_values("track_position")["t"].values)
G["telediff"] = {"ta_s": arr(ta_s[:50]), "d_speed": arr((vb_speed - va_speed)), "d_t": arr(vb_t - va_t)}
